        let fragmentFinish = timestamps[3].timestamp

        let fragmentTime = timeConverter.microsecondsBetween(begin: fragmentStart,
                                                             end: fragmentFinish)

        let roundedTime = String(format: "%.2f", fragmentTime)
        print("    Fragment duration: \(roundedTime) µS")
    }
}

